from datetime import datetime

def hydrate_time(nanoseconds, tz=None):
    if nanoseconds < 0:
        raise ValueError("Negative nanoseconds are not supported")
    if tz is None:
        tz = datetime.now().tzname
    days, seconds, microseconds = divmod(nanoseconds, 864000000000)
    hours, seconds = divmod(seconds, 36000000000)
    minutes, seconds = divmod(seconds, 60000000)
    seconds, microseconds = divmod(seconds, 1000000)
    return datetime.fromtimestamp(days + hours / 24 + minutes / (3600 * 24) + seconds / (3600 * 24 * 60) + microseconds / (1000000 * 3600 * 24 * 60), tzname=tz)

