def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass."""

    if isinstance(fields, str):
        fields = [fields]

    fields_dict = {f: 'float' for f in fields if f != 'x' and f != 'y' and f != 'srid'}

    class BasePoint:
        pass

    class MetaPoint(BasePoint):
        def __init__(self, x=None, y=None, srid=None):
            if srid_map and srid in srid_map:
                srid = srid_map[srid]
            self.x = x
            self.y = y
            self.srid = srid

        def __repr__(self):
            return f"{self.__class__.__name__}(x={self.x}, y={self.y}, srid={self.srid})"

        def __eq__(self, other):
            return self.x == other.x and self.y == other.y and self.srid == other.srid

    class Point(BasePoint):
        def __new__(cls, *args, **kwargs):
            if args or kwargs:
                if len(args) != len(fields) + 1 or (
                    len(args) > 1 and 'srid' not in kwargs
                ):
                    raise TypeError(
                        f"Expected {len(fields) + 1} arguments, got {len(args) + len(kwargs)}"
                    )
                if 'srid' in kwargs and kwargs['srid'] not in srid_map:
                    raise ValueError(f"Invalid SRID: {kwargs['srid']}")
                x = args[1] if len(args) == 2 else None
                y = args[2] if len(args) == 3 else None
            else:
                x = kwargs.get('x', None)
                y = kwargs.get('y', None)
                srid = kwargs.get('srid', None)

            if srid_map and srid in srid_map:
                srid = srid_map[srid]
            elif srid is None:
                srid = 4326

            if x is None and y is None:
                raise ValueError("At least one of x and y must be provided")

            obj = super().__new__(cls)
            obj.x = x
            obj.y = y
            obj.srid = srid
            return obj

        def __repr__(self):
            return f"{self.__class__.__name__}(x={self.x}, y={self.y}, srid={self.srid})"

        def __eq__(self, other):
            return self.x == other.x and self.y == other.y and self.srid == other.srid

    return BasePoint, MetaPoint, Point

