import functools

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def _deprecated自身的_function_wrapper(function):
        if isinstance(function, type):
            raise TypeError("Decorating a class with deprecated is not supported")

        code = (function.__doc__ or "").expandtabs()
        function.__doc__ = code + "\n\n" + message

        @functools.wraps(function)
        def _inner(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=3)
            return function(*args, **kwargs)

        return _inner

    return _deprecated自身的_function_wrapper

