def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    m = re.match(r'(\d+)\.(\d+)(\.\d+)?', s)
    if not m:
        raise ValueError(f"Incorrect version format: {s}")

    return tuple(int(v) for v in m.groups())

