def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.

    """
    cache = collections.OrderedDict()
    hit_cache = collections.OrderedDict()

    def decorator(func):
        if ttl <= 0:
            return func

        def wrapper(*args, **kwargs):
            key = func.__name__ + ''.join([f"*{arg}" for arg in args]) + ''.join([f"*{k}={v}" for k, v in kwargs.items()])
            if key in cache:
                if timer() - cache[key] <= ttl:
                    hit_cache[key] = (cache[key], func(*args, **kwargs))
                    cache[key] = None
            elif len(cache) < maxSize:
                cache[key] = func(*args, **kwargs)
            else:
                oldest_hit = min(hit_cache, key=hit_cache.get)
                if oldest_hit in cache:
                    del cache[oldest_hit]
                    cache[key] = func(*args, **kwargs)
                    hit_cache[key] = (cache[key], func(*args, **kwargs))
                    hit_cache[oldest_hit] = None
            return cache[key]

        return wrapper

    return decorator

from functools import lru_cache, wraps

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            key = hash(args) + hash(kwargs)
            try:
                return lru_cache(maxsize, typed)(fn)(key)
            except KeyError:
                v = fn(key)
                lru_cache(maxsize, typed).cache_set(key, v)
                return v
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    class LFUCache(dict):
        def _update(self, key, value):
            if key in self:
                self[key]['count'] += 1
            elif len(self) >= maxsize:
                oldest_key = min(self.keys(), key=self.get)
                del self[oldest_key]
            self[key] = {'value': value, 'count': 1}

        def __delitem__(self, key):
            self._update(key, None)
            super().__delitem__(key)

    if typed:
        cache = LFUCache(key_factory=functools.partial(hash, typed))
    else:
        cache = LFUCache(key_factory=lambda x: x)

    def decorator(func):
        wrapped = functools.wraps(func)(partial(_memoized_call, func, cache))
        wrapped.memoize_cache = cache
        return wrapped

    return decorator

