def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def check_classes(base, seen):
        if base in seen:
            return
        seen.add(base)
        bases.append(base)
        for b in check_classes(base.__bases__, seen):
            bases.append(b)

    seen = set()
    bases = []

    for base in classes:
        check_classes(base, seen)

    return bases

