    new_sql = ""

    bound_paramIndices = []

    i = 0
    for many_param in many_params:
        parameters = many_param.items()
        key = next(iter(parameters))

        if key in hardcoded_in_placeholders or key in self._backwards_compatability:
            in_style_name = self._backwards_compatibility[key] if key in self._backwards_compatability else self._get_sql_params().get_in_style()
            if in_style_name == "named":
