                    raise ValueError(f"Parameters are expected in form of mapping but got {single_param[key]}")
                param_dict = single_param[key]
                converted_params = []
                for key2, single_param2 in param_dict.items():
                    converted_params.append(f":{key2}")
                converted_many_params.append(converted_params)
            elif in_style_name == "ordinal":
