            else:
                raise ValueError(f"Unexpected string SQL parameter style: {in_style_name}")
        else:
            raise ValueError(f"Invalid column name: {key}")

        bound_paramIndices.append(len(new_sql))

        new_sql += f"""{" ".join([f":{key}" if key in hardcoded_in_placeholders or key in self._backwards_compatability else key for key in parameters])}"""

    while len(bound_paramIndices) < sum(len(param) for param in converted_many_params):
        bound_paramIndices.append(len(new_sql))

    bound_paramIndices.extend(bound_paramIndices)

    for i in reversed(bound_paramIndices):
        new_sql = new_sql[0:i] + "?" + new_sql[i:]

    return new_sql, converted_many_params

import os

class Validator:
    def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        if not path:
            return False

        if not os.path.exists(path):
            return False

        opath = path
        if os.path.isdir(path):
            opath = path + '/'

        for _, dirlist, filelist in os.walk(opath):
            for file in filelist:
                filename_with_path_obj = os.path.join(opath, file)
                if not self.is_valid_pyos_filename(filename_with_path_obj) or \
                    not FileHandling.is_valid_file(open(filename_with_path_obj, 'rb')):  # pylint: disable=E1123
                    return False

        return True

    def is_valid_pyos_filename(self, filename_with_path_obj):
        """Returns True if valid PyOS filename

        Args:
            filename_with_path_obj (str): the filename with path/object

        Returns:
            bool: True if valid, False otherwise
        """
        # Christian seems to need this, we need to avoid: ~ as a filename
        disallowed_chars = '~'
        for char in disallowed_chars:
            if char in filename_with_path_obj:
                return False

        return True

