def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if expr[0] and expr[2]:
            if expr[0] is expr[2]:
                return [expr[0]]
            else:
                return [expr[0], expr[2]]
        return expr

    def apply_negative_absorption(expr):
        if expr[0] and expr[2]:
            if expr[0] is expr[2]:
                return [expr[0]]
            else:
                return [expr[0], expr[2]]
        return expr

    absorb_actions = {
        'A & (A | B)': apply_absorption,
        'A | (A & B)': apply_absorption,
        'A & (~A | B)': apply_negative_absorption,
        'A | (~A & B)': apply_negative_absorption
    }

    absorbed_args = []
    for arg in args:
        if arg in absorb_actions:
            absorbed_args.extend(absorb_actions[arg](arg.split()))
        else:
            absorbed_args.append(arg)

    return absorbed_args

