def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if isinstance(version, str):
        version = version.replace("0", "").lstrip("0")
        if version:
            split_version = version.split('.')
            major = int(split_version[0]) + 1
            minor = int(split_version[1])
            patch = int(split_version[2])
        else:
            major, minor, patch = 1, 0, 0
    elif isinstance(version, int):
        major = version // 1000
        minor = (version - major * 1000) // 100
        patch = version - major * 1000 - minor * 100
    else:
        raise ValueError("Invalid input type")

    if major < 100:
        major = 0
    if major < 10:
        major = 0
    if minor < 10:
        minor = 0
    if patch < 10:
        patch = 0

    if not major:
        return "0.0.1"
    if not major and not minor:
        return "0.1.1"
    if not major and not minor and not patch:
        return "1.1.1"

    return f"{major}.{minor}.{patch}"

