import re

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    def is_glob_pattern(path):
        # A glob pattern starts with a '**' at the beginning
        return path.startswith('sh:*')

    def get_glob_path(path):
        # For glob patterns, simply use the path as is.
        return path

    def get_path_pattern(path):
        # For non-glob paths, convert them to a path pattern.
        return f"{path}" if "*" in path else f"sh:{path}"

    result = []
    for path in find_paths:
        if is_glob_pattern(path):
            result.append(get_glob_path(path))
        else:
            result.append(get_path_pattern(path))
    return result

