def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if not graph:
        raise ValueError("graph must be provided")

    if not isinstance(prop, URIRef):
        raise ValueError("prop must be a URIRef")

    # Use a set to store the roots for O(1) average case lookups
    if roots is None:
        roots = set()

    # Initialize the working set with roots
    working_set = {v for k, v in graph.subject_objects(prop) if v not in graph.objects(prop)}

    # Use a set to keep track of nodes seen to avoid infinite loops
    seen_nodes = set()

    # Perform BFS to find all roots
    while working_set:
        node = working_set.pop()
        if node not in seen_nodes:
            seen_nodes.add(node)
            # Get the parents of the current node
            parents = set(graph.subject_objects(prop, node))
            # Add the parent to the working set if it is not a root yet
            for parent in parents:
                if parent not in seen_nodes:
                    working_set.add(parent)
            # Update the roots set to include the current node
            roots.add(node)

    return roots

