def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    metaclasses = []

    # Iterate throughbases to gather metaclasses
    for base in bases:
        if base.__class__ == type Metaclass:
            metaclasses.append(base)

    # If explicit_mc is provided, it should take priority over metaclasses in bases
    if explicit_mc:
        metaclasses.insert(0, explicit_mc)

