@classmethod
    def validate_from_content(cls, spec_content=None):
        if spec_content is None:
            raise IRValidatorException("spec_content argument must be supplied")
        required_fields = cls._get_required_fields(spec_content)
        missing_fields = set(required_fields) - cls._get_fields(spec_content)
        if missing_fields:
            raise IRValidatorException(f"Missing required fields in spec: {missing_fields}")
        return cls._load_data_from_spec(spec_content)

import yaml

class IRValidatorException(Exception):
    pass

def validate_yaml_file(schema: dict, yaml_file: Path):
    """Validates yaml data against the defined schema

    :param schema: schema in json format
    :param yaml_file: path to yaml_file
    :return:
    """

    with yaml_file.open() as f:
        data = yaml.load(f)

    jsonschema.validate(data, schema)

def validate_from_file(cls, yaml_file=None):
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")

    # Load the YAML file
    try:
        with open(yaml_file, 'r') as file:
            data = yaml.safe_load(file)
    except FileNotFoundError:
        raise IRValidatorException(f"YAML file {yaml_file} not found")
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Invalid YAML content: {e}")

    # Validate the data against the schema
    try:
        jsonschema.validate(data, cls.yaml_schema)
    except jsonschema.exceptions.ValidationError as ve:
        raise IRValidatorException(f"Validation failed: {ve}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for include in parser_dict.values():
        if isinstance(include, dict) and include.get('directive', '') == 'include':
            sub_parser = self._get_sub_parser_from_directive(include.get('source', ''))
            if sub_parser:
                self._merge_parsers(parser_dict, include, sub_parser)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""

    spec_defaults = self.spec.get(**self.args)
    external_defaults = self._external_source.get(**self.args)

    # Handle nested schemes
    for arg in self.args:
        if isinstance(arg, NestedOption):
            nested_defaults = arg.scheme.get_spec_defaults()
            spec_defaults.update(nested_defaults)

    combined_defaults = {**spec_defaults, **external_defaults}
    return combined_defaults

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""

    if command_name not in self._command_names:
        raise ValueError(f"Command '{command_name}' is not recognized.")

    spec = self._option_specs[command_name]

    if argument_name not in spec['options']:
        raise ValueError(f"Option '{argument_name}' for command '{command_name}' is not recognized.")

    result = spec['options'][argument_name]

    return result

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.

    :param args: Passed command line arguments.
    """
    required_args = ['arg1', 'arg2', 'arg3']
    for arg in required_args:
        if arg not in args:
            raise MissingArgumentError(f"The argument '{arg}' is required but not provided.")

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.string_limit:
            raise ValueError(f" Argument '{arg}' exceeds the maximum length allowed ({self.string_limit}).")
        if isinstance(arg, list) and len(arg) > self.list_limit:
            raise ValueError(f"Arguments in list exceed the maximum length allowed ({self.list_limit}).")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    allowed_choices = ['choice1', 'choice2', 'choice3']  # Define your allowed choices here
    for key, value in args.items():
        if value not in allowed_choices:
            raise ValueError("Invalid choice for {}".format(key))

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    custom_args = []
    other_args = []

    for arg in args:
        if arg.startswith('control'):
            control_args[arg[len('control'):]] = True
        elif arg.startswith('nested'):
            nested_args[arg[len('nested'):]] = True
        elif arg.startswith('custom'):
            custom_args.append(arg)
        else:
            other_args.append(arg)

    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """

    if not vars_dict:
        return extra_vars

    if not extra_vars:
        return vars_dict

    else:
        vars_dict.update(extra_vars)
        return vars_dict

